import axios from 'axios'
import { Message, Loading } from 'element-ui' // 假设使用 Element UI 作为 UI 库

// 创建 axios 实例
const service = axios.create({
  baseURL: process.env.VUE_APP_BASE_API, // 从环境变量获取基础 URL
  timeout: 10000, // 请求超时时间
  headers: {
    'Content-Type': 'application/json;charset=utf-8'
  }
})

// 加载动画实例
let loadingInstance = null
//存储所有请求的函数
let cancelTokenSources = []
// 清除所有请求
const cancelAllRequests = () => {
  cancelTokenSources.forEach(source => {
    source.cancel('因请求异常，已取消其他所有请求')
  })
  cancelTokenSources = []
}
// 请求拦截器
service.interceptors.request.use(
  config => {
    // 显示加载动画
    loadingInstance = Loading.service({
      lock: true,
      text: '加载中...',
      background: 'rgba(0, 0, 0, 0.7)'
    })
    //创建取消令牌
    const source = axios.CancelToken.source()
    config.cancelToken = source.token
    cancelTokenSources.push(source)

    // 添加 token（根据实际项目的认证方式调整）
    const token = localStorage.getItem('token')
    if (token) {
      config.headers.Authorization = `Bearer ${token}`
    }
    const userName = localStorage.getItem("userName")
    config.headers["user_name"] = userName
    return config
  },
  error => {
    // 隐藏加载动画
    if (loadingInstance) loadingInstance.close()
    // 处理请求错误
    Message.error('请求发送失败，请稍后重试')
    console.error('请求错误:', error)
    return Promise.reject(error)
  }
)

// 响应拦截器
service.interceptors.response.use(
  response => {
    // 隐藏加载动画
    if (loadingInstance) loadingInstance.close()
      //从取消列表中移除已完成的请求
      cancelTokenSources = cancelTokenSources.filter(
        source => source.token !== response.config.cancelToken
      )
    const res = response.data

    // 根据后端约定的状态码处理
    if (res.code !== 200) {
      // 错误提示
      Message.warning(res.message || '操作失败')
      
      // 特殊状态码处理（例如 token 过期）
      if (res.code === 401) {
        // 清除 token 并跳转登录页
        localStorage.removeItem('token')
        window.location.href = '/login'
        Message.info(res.message)
      }
    }
      return res

  },
  error => {
    // 隐藏加载动画
    if (loadingInstance) loadingInstance.close()
    // 如果是取消请求的错误，不做处理
    if (axios.isCancel(error)) {
      console.log('请求已取消:', error.message)
      return Promise.reject(error)
    }
     // 取消所有请求,防止多次请求
     cancelAllRequests()
    // 处理响应错误
    let errorMsg = '网络错误，请检查网络连接'
    if (error.response) {
      switch (error.response.status) {
        case 404:
          errorMsg = '请求的资源不存在'
          break
        case 500:
          errorMsg = '服务器内部错误'
          break
        case 403:
          errorMsg = '没有权限访问'
          break
        default:
          errorMsg = `请求错误 (${error.response.status})`
      }
    }
    Message.error(errorMsg)
    console.error('响应错误:', error)
    return Promise.reject(error)
  }
)

// 常用请求方法封装
const request = {
  /**
   * GET 请求
   * @param {string} url - 请求地址
   * @param {object} params - 请求参数
   * @param {object} config - 额外配置
   * @returns {Promise}
   */
  get(url, params = {}, config = {}) {
    return service.get(url, { params, ...config })
  },

  /**
   * POST 请求
   * @param {string} url - 请求地址
   * @param {object} data - 请求数据
   * @param {object} config - 额外配置
   * @returns {Promise}
   */
  post(url, data = {}, config = {}) {
    return service.post(url, data, config)
  },

  /**
   * PUT 请求
   * @param {string} url - 请求地址
   * @param {object} data - 请求数据
   * @param {object} config - 额外配置
   * @returns {Promise}
   */
  put(url, data = {}, config = {}) {
    return service.put(url, data, config)
  },

  /**
   * DELETE 请求
   * @param {string} url - 请求地址
   * @param {object} params - 请求参数
   * @param {object} config - 额外配置
   * @returns {Promise}
   */
  delete(url, params = {}, config = {}) {
    return service.delete(url, { params, ...config })
  },

  /**
   * 上传文件
   * @param {string} url - 请求地址
   * @param {FormData} formData - 包含文件的 FormData 对象
   * @param {object} config - 额外配置
   * @returns {Promise}
   */
  upload(url, formData, config = {}) {
    return service.post(url, formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
      ...config
    })
  }
}

export default request
    